/** Map gallery catalog ids like `antigravity-blob-render` → sealed plugin id. */
export function pluginIdFromBlobRenderCatalogId(catalogId: string): string | null {
  if (catalogId === "antigravity-blob-render") return "antigravity";
  if (catalogId === "antigravity_chat-blob-render" || catalogId === "antigravity-chat-blob-render") {
    return "antigravity_chat";
  }
  const match = catalogId.match(/^(.+)-blob-render$/);
  if (!match) return null;
  return match[1].replace(/-/g, "_");
}

export interface AntigravityGalleryBundle {
  sealed: SealedPluginGalleryEntry[];
  chat: {
    id: string;
    name: string;
    path: string;
    schema_hash?: string;
  } | null;
}

/** Antigravity gallery bundle: sealed blobs + the zeroclaw /chat UI surface. */
export async function fetchAntigravityGalleryBundle(): Promise<AntigravityGalleryBundle> {
  const [sealed, zeroclawEnvelope] = await Promise.all([
    fetchSealedPluginGalleryEntries(["antigravity", "antigravity_chat"]),
    fetchPluginSchema("zeroclaw").catch(() => null),
  ]);

  const chatSurface = zeroclawEnvelope
    ? parsePluginUiSurfaces(zeroclawEnvelope).find(
        (surface) => surface.path === "/chat" || /antigravity chat/i.test(surface.name),
      )
    : undefined;

  return {
    sealed,
    chat: chatSurface
      ? {
          id: `zeroclaw${chatSurface.path}`,
          name: chatSurface.name,
          path: chatSurface.path,
          schema_hash: zeroclawEnvelope?.schema_hash,
        }
      : null,
  };
}

