          };
        } catch {
          return { ...entry, source: "catalog" as const, managed: true };
        }
      }),
    );
    setEntries((prev) => ({ ...prev, catalog: hydrated }));
    setSource("catalog", { status: "ok", count: hydrated.length });
  } catch (e) {
    setEntries((prev) => ({ ...prev, catalog: [] }));
    setSource("catalog", classifyError(e));
