export const dbusPassthrough = {
  call(req: {
    bus: string;
    destination: string;
    path: string;
    interface: string;
    method: string;
    jsonBody: string;
  }) {
    return grpcUnary<
      {
        bus: string;
        destination: string;
        path: string;
        interface: string;
        method: string;
        json_body: string;
      },
      { success: boolean; json_result: string; error: string }
    >("operation.v1.DbusPassthrough", "Call", {
      bus: req.bus,
      destination: req.destination,
      path: req.path,
      interface: req.interface,
      method: req.method,
      json_body: req.jsonBody,
    });
  },

  get(req: {
    bus: string;
    destination: string;
    path: string;
    interface: string;
    property: string;
  }) {
    return grpcUnary<
      {
        bus: string;
        destination: string;
        path: string;
        interface: string;
        property: string;
      },
      { success: boolean; json_value: string; error: string }
    >("operation.v1.DbusPassthrough", "Get", req);
  },

  set(req: {
    bus: string;
    destination: string;
    path: string;
    interface: string;
    property: string;
    json_value: string;
  }) {
    return grpcUnary<
      {
        bus: string;
        destination: string;
        path: string;
        interface: string;
        property: string;
        json_value: string;
      },
      { success: boolean; error: string }
    >("operation.v1.DbusPassthrough", "Set", req);
  },

  watch(req: {
    bus: string;
    destination: string;
    path: string;
    interface: string;
    signal_names?: string[];
  }) {
    return grpcServerStream<
      {
        bus: string;
        destination: string;
        path: string;
        interface: string;
        signal_names: string[];
      },
      {
        signal_name: string;
        path: string;
        interface: string;
